mapper.select:
SELECT COUNT(1) FROM assess_mgmt
WHERE deleted = 0

    AND grade = #{grade}


    AND major = #{major}


    AND assess_type = #{assessType}


    AND status = #{status}

SELECT AVG(score) FROM assess_mgmt
WHERE deleted = 0

    AND grade = #{grade}


    AND major = #{major}


    AND assess_type = #{assessType}


    AND status = #{status}

SELECT COUNT(1) FROM assess_mgmt
WHERE deleted = 0 AND status = '已发布' AND publish_time >= DATE(NOW()) AND publish_time < DATE(NOW())

    AND grade = #{grade}


    AND major = #{major}

SELECT class_name, AVG(CASE WHEN assess_type = '1' THEN score ELSE NULL END) AS classCleanScore, AVG(CASE WHEN assess_type = '2' THEN score ELSE NULL END) AS morningExerciseScore, AVG(CASE WHEN assess_type = '3' THEN score ELSE NULL END) AS civilClassScore, AVG(CASE WHEN assess_type = '4' THEN score ELSE NULL END) AS blackboardScore, AVG(score) AS totalScore FROM assess_mgmt WHERE deleted = 0 AND status = '1'
AND cycle = #{cycle}
GROUP BY class_name ORDER BY totalScore DESC
